'use strict';
const analysisFiles=new Map();
function analysisAvailable(p){return p.stage>=6||p.publicationRegistered===true;}
function analysisCallout(p){const done=!!p.analysisReport;return `<div class="analysis-callout"><div><span class="eyebrow">VIDEO INSIGHTS</span><h3>${done?'查看这条视频的内容分析':'发布之后，再认真看一遍内容。'}</h3><p>开头、叙事、口播、画面与节奏，结合数据找到下一条的参考方向。</p></div>${linkBtn(done?'查看视频分析':'分析这条视频','analysis/'+p.id,'primary','video')}</div>`;}
function analysisPage(id){
if(!id){const ps=scoped().filter(analysisAvailable);return heading('LOOK CLOSER. CREATE BETTER.','视频分析，让判断更具体。','把成片里的内容表现，与发布后的数据放在一起。')+notice('当前支持本地视频预览、人工观察记录和数据联动。分析建议采用规则模拟，不会自动识别视频画面、转写音频或抓取平台链接。')+`<div class="grid3">${ps.map(p=>`<section class="panel hot-card"><div class="card-top">${pill(creator(p.creatorId).name)}${pill(p.analysisReport?(JimuAnalysis.isCurrent(p)?'已生成分析':'待更新分析'):'待分析',p.analysisReport?'':'amber')}</div><h3>${esc(p.title)}</h3><p>${p.metrics&&p.stage>=6?`${compact(p.metrics.plays)} 播放 · ${p.metrics.completion}% 完播 · ${p.metrics.window}h`:'已登记发布，等待统计窗口结束后补录数据。'}</p><div class="source">${esc(p.platform||'平台待填')} · 发布 ${date(p.publishedAt)}<br>${p.analysisReport?esc(p.analysisReport.evidenceSource)+' · '+date(p.analysisReport.generatedAt,true):'先看成片，记录具体内容依据。'}</div>${linkBtn('打开视频分析','analysis/'+p.id,'primary','arrow')}</section>`).join('')}</div>${ps.length?'':empty('发布之后，从这里分析','先在视频项目里登记发布信息，即可开始内容分析。',linkBtn('前往制作中心','production'))}`;}
const p=S.projects.find(p=>p.id===id);if(!p||!analysisAvailable(p))return empty('先登记视频发布信息','发布登记后，即可开始视频内容分析。',linkBtn('返回视频项目',p?'project/'+p.id:'production'));const a=JimuAnalysis.normalize(p.videoAnalysis),r=p.analysisReport,fullData=p.stage>=6&&p.metrics;
return heading('VIDEO CONTENT × PERFORMANCE',esc(p.title),`${esc(creator(p.creatorId).name)} · ${esc(p.platform)} · 发布 ${date(p.publishedAt)}`,linkBtn('返回视频项目','project/'+p.id,'','back'))+`<div class="subnav"><a href="#analysis">全部已发布视频</a><span class="pill">视频内容＋数据表现</span></div>${notice('分析模式：人工观察＋规则模拟。可以在下方播放本地成片、填写逐字稿与观察记录；未接入自动看视频或语音识别服务。','amber')}<div class="analysis-layout"><aside class="analysis-side"><section class="panel"><div class="section-head"><h2>${icon('play',16)} 成片预览</h2>${pill('本地读取','gray')}</div><div id="analysis-player-wrap"><div class="analysis-player-empty">${icon('video',38)}<b>回到内容发生的现场</b><p>关联本地成片，边看边记录。<br>文件不会上传到服务器。</p></div></div><label class="analysis-file">${icon('plus',16)} 选择 / 重新关联本地视频<input id="analysis-video-input" type="file" accept="video/*" data-id="${p.id}" aria-label="选择本地视频"></label><div id="analysis-material-info" class="copy">${a.material?`${esc(a.material.name)} · ${a.material.duration.toFixed(1)} 秒 · ${a.material.width} × ${a.material.height}<br>刷新后需重新选择文件，观察和报告会保留。`:'支持浏览器可播放的 MP4 / WebM 等格式。'}</div>${safeUrl(p.publishUrl)?`<a class="source-link copy" style="display:inline-block;margin-top:14px" href="${esc(safeUrl(p.publishUrl))}" target="_blank" rel="noopener noreferrer">打开已发布视频 ↗</a>`:'<p class="copy" style="margin-top:12px">发布链接尚未填写，可在下方补充。</p>'}</section><section class="panel"><div class="section-head"><h2>这条视频的数据</h2>${pill(fullData?`${p.metrics.window}h`:'待补录','gray')}</div>${fullData?`<div class="analysis-data"><div><small>播放量</small><b>${compact(p.metrics.plays)}</b></div><div><small>完播率</small><b>${p.metrics.completion}%</b></div><div><small>评论</small><b>${fmt(p.metrics.comments)}</b></div><div><small>收藏</small><b>${fmt(p.metrics.saves)}</b></div></div><p class="copy">${esc(p.metrics.source)} · 采集 ${date(p.metrics.collectedAt,true)}</p>`:'<p class="copy">发布后可先分析内容；统计窗口结束后，再登记数据进行对照。</p>'}<div style="margin-top:18px">${linkBtn(fullData?'打开数据复盘':'补录发布数据','project/'+p.id,'small','chart')}</div></section><section class="panel"><h3 style="font-size:13px;margin-bottom:13px">分析顺序</h3><p class="copy">01 看成片，留下具体观察<br>02 对照数据，列出待验证的判断<br>03 带入复盘，由编导逐条确认<br>04 关联下一条策划</p></section></aside><div><section class="panel"><div class="section-head"><h2>内容观察</h2>${btn('填入示例观察','analysis-example',p.id,'small soft','spark')}</div><form id="analysis-form" data-id="${p.id}" class="form-section">${field('发布视频链接（选填）','publishUrl',p.publishUrl||'','url','placeholder="https://…"')}${select('内容记录来源','evidenceSource',['人工观察','示例观察'],a.evidenceSource)}<div class="analysis-dimensions">${JimuAnalysis.fields.map((f,i)=>`<div class="analysis-dimension"><div class="section-head"><h3><span>0${i+1}</span>${f.label}</h3><select name="judgment-${f.key}" aria-label="${f.label}判断">${options([['unknown','暂不判断'],['strength','可保留'],['improve','待调整']],a.notes[f.key].judgment)}</select></div><label>${f.prompt}<textarea name="note-${f.key}" maxlength="6000" placeholder="写具体观察，如：前 8 秒都在交代背景，到第 9 秒才出现孩子的动作。">${esc(a.notes[f.key].text)}</textarea></label></div>`).join('')}</div><details><summary class="copy">补充逐字稿与评论（选填）</summary><div class="form-section" style="margin-top:16px">${area('成片逐字稿 / 字幕','transcript',a.transcript,'maxlength="40000" placeholder="手动粘贴实际口播或字幕。不会自动转写，也不会将策划脚本冒充实际成片。"')}${area('观众评论原文与来源','comments',a.comments,'maxlength="40000" placeholder="粘贴有代表性的评论，注明来源；不要凭评论数量推断动机。"')}</div></details><details><summary class="copy">补充留存与观看指标（选填）</summary><div class="form-grid" style="margin-top:16px">${field('前 5 秒留存率 (%)','retention5',a.extra.retention5??'','number','min="0" max="100" step="0.01"')}${field('2 秒跳出率 (%)','bounce2',a.extra.bounce2??'','number','min="0" max="100" step="0.01"')}${field('平均观看时长（秒）','avgWatch',a.extra.avgWatch??'','number','min="0" step="0.1"')}${field('补充指标来源与统计窗口','extraSource',a.extra.source,'text','placeholder="例如：抖音创作者中心，发布后24小时"')}</div></details><div class="form-footer"><button class="btn" type="submit">保存内容观察</button>${btn(r?'重新生成视频分析':'生成视频分析','analysis-generate',p.id,'primary','spark')}</div></form></section>${analysisReportPanel(p)}</div></div>`;
}
function analysisReportPanel(p){const r=p.analysisReport;if(!r)return `<section class="panel" id="analysis-report">${empty('让每个判断，都有具体依据','至少填写一项内容观察、逐字稿或评论，即可生成模拟分析。')}</section>`;const current=JimuAnalysis.isCurrent(p);return `<section class="panel" id="analysis-report"><div class="section-head"><h2>视频分析报告</h2>${pill('规则模拟','amber')}</div>${notice(`${esc(r.mode)}。<br>生成于 ${date(r.generatedAt,true)} · 内容依据：${esc(r.evidenceSource)}`)}${!current?notice('观察记录或数据已更改，这份报告需要重新生成。旧报告暂时不能带入复盘。','amber'):''}<h3 class="analysis-report-title">01 / 内容观察与判断</h3>${r.findings.length?r.findings.map(f=>`<article class="analysis-finding"><div class="section-head"><h3>${esc(f.title)}</h3>${pill(f.judgment==='strength'?'可保留':f.judgment==='improve'?'待调整':'未判断',f.judgment==='improve'?'amber':'gray')}</div><blockquote>${esc(f.evidence)}</blockquote><p class="copy">${esc(f.interpretation)}</p></article>`).join(''):'<p class="copy">已保存文本材料，但缺少分维度观察，当前无法判断画面、开头或节奏。</p>'}${r.missing.length?`<p class="copy" style="margin-top:16px">尚未观察：${r.missing.map(esc).join('、')}。不对缺失内容自动打分。</p>`:''}<p class="copy" style="margin-top:10px">逐字稿已记录 ${r.transcriptChars} 字；文字长度不能代表实际语速或表达质量。</p><h3 class="analysis-report-title">02 / 数据对照</h3><p class="copy">${r.data?esc(r.data.summary):'尚未登记完整表现数据，内容观察暂不进行效果归因。'}</p>${r.data?`<p class="copy">同达人、同平台、同统计窗口的既往样本：${r.data.sampleIds.length} 条。互动率 ${(r.data.interactionRate).toFixed(2)}%，含赞评藏转，非去重人数。</p>`:''}<div class="analysis-extra">${[['前5秒留存',r.extra.retention5,'%'],['2秒跳出',r.extra.bounce2,'%'],['平均观看时长',r.extra.avgWatch,'秒']].map(([t,v,u])=>`<span>${t}：${v===null?'未提供':esc(v)+u}</span>`).join('')}</div>${r.extra.source?`<p class="copy">补充指标来源：${esc(r.extra.source)}；口径由录入者核对，不自动与其他窗口合并。</p>`:''}<h3 class="analysis-report-title">03 / 下一条的参考调整</h3>${r.suggestions.map((s,i)=>`<article class="suggestion"><h3>0${i+1} · ${esc(s.title)}</h3><p class="copy">${esc(s.text)}</p><div class="basis">依据：${esc(s.basis)}</div></article>`).join('')}<div class="form-footer">${btn('导出分析报告','analysis-export',p.id,'','download')}${p.stage===6?`<button type="button" class="btn primary" data-action="analysis-to-review" data-id="${p.id}" ${current?'':'disabled'}>带入复盘，等待编导确认 ${icon('arrow',14)}</button>`:linkBtn(p.stage===7?'查看已确认方向':'补录数据后再确认方向','project/'+p.id,'primary','arrow')}</div><p class="copy">带入后仍需逐条采纳、修改或拒绝，并亲自确认最终方向。</p></section>`;}
function saveAnalysisForm(){const f=$('#analysis-form'),d=validForm(f),p=currentProject(f.dataset.id),old=JimuAnalysis.normalize(p.videoAnalysis),a=JimuAnalysis.blank();a.evidenceSource=d.evidenceSource;a.material=old.material;a.transcript=d.transcript||'';a.comments=d.comments||'';for(const row of JimuAnalysis.fields)a.notes[row.key]={judgment:d['judgment-'+row.key],text:d['note-'+row.key].trim()};for(const k of ['retention5','bounce2','avgWatch'])a.extra[k]=d[k]===''?null:Number(d[k]);a.extra.source=d.extraSource.trim();JimuAnalysis.validate(a);p.videoAnalysis=a;p.publishUrl=d.publishUrl.trim();p.updatedAt=C.iso();persist();return p;}
function mountAnalysisPlayer(id){const holder=$('#analysis-player-wrap');if(!holder||!id)return;const file=analysisFiles.get(id);if(!file)return;const v=document.createElement('video');v.controls=true;v.preload='metadata';v.playsInline=true;v.className='analysis-player';let probing=false;
function saveMetadata(){if(!Number.isFinite(v.duration)||v.duration<=0)return;const p=currentProject(id);p.videoAnalysis=JimuAnalysis.normalize(p.videoAnalysis);p.videoAnalysis.material={name:file.name,size:file.size,duration:v.duration,width:v.videoWidth,height:v.videoHeight};persist();const info=$('#analysis-material-info');if(info)info.textContent=`${file.name} · ${v.duration.toFixed(1)} 秒 · ${v.videoWidth} × ${v.videoHeight}。刷新后重新选择视频，记录仍保留。`;if(p.analysisReport&&$('#analysis-report'))$('#analysis-report').outerHTML=analysisReportPanel(p);if(probing){probing=false;v.currentTime=0;}}
v.addEventListener('loadedmetadata',()=>{if(v.duration===Infinity){probing=true;v.currentTime=1e10;}else saveMetadata();});v.addEventListener('durationchange',saveMetadata);v.addEventListener('error',()=>toast('此文件无法播放，请使用浏览器支持的 MP4 或 WebM 视频。',true));v.src=file.url;holder.replaceChildren(v);}

function analysisExport(p){const r=p.analysisReport;return `${p.title}｜视频分析\n${creator(p.creatorId).name} · ${p.platform}\n${r.mode}\n内容来源：${r.evidenceSource}；生成时间：${r.generatedAt}\n${JimuAnalysis.isCurrent(p)?'报告对应当前已保存记录':'注意：观察或数据已变更，报告待更新'}\n\n内容观察\n${r.findings.map(f=>`${f.title}：${f.evidence}\n${f.interpretation}`).join('\n\n')}\n\n数据对照\n${r.data?.summary||'数据待补充'}\n补充指标：${JSON.stringify(r.extra)}\n\n参考建议（需编导确认）\n${r.suggestions.map(s=>`${s.title}\n依据：${s.basis}\n建议：${s.text}`).join('\n\n')}`;}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;if(!action.startsWith('analysis-')&&action!=='register-publication')return;try{const p=currentProject(id);
if(action==='register-publication'){const f=$('#publish-form'),names=['platform','publishedAt','publishUrl'];for(const n of names)if(!f.elements[n].reportValidity())return;const pub=new Date(f.elements.publishedAt.value);if(isNaN(pub)||pub>new Date())throw Error('请输入有效的已发布时间。');Object.assign(p,{platform:f.elements.platform.value,publishedAt:pub.toISOString(),publishUrl:f.elements.publishUrl.value,publicationRegistered:true});p.history.push({action:'registerPublication',at:C.iso(),by:S.preferences.reviewer});persist('发布已登记，可以先分析内容，再补录数据');go('analysis/'+p.id);return;}
if(action==='analysis-example'){confirmModal('填入示例内容观察','这会替换本页当前的观察和补充文本，并明确标注为示例。已有视频、数据和确认方向保持不变。','analysis-confirm-example',id,'填入示例');return;}
if(action==='analysis-confirm-example'){const a=JimuAnalysis.blank();a.material=p.videoAnalysis?.material||null;a.evidenceSource='示例观察';a.notes.opening={judgment:'improve',text:'示例：前 8 秒在说明出游准备，到第 9 秒才出现孩子自己挑选物品的动作。'};a.notes.story={judgment:'strength',text:'示例：挑选、装包、实际使用形成了完整过程，孩子的选择贯穿始终。'};a.notes.pacing={judgment:'improve',text:'示例：中段连续两次解释同一件物品的用途，信息有所重复。'};a.notes.ending={judgment:'strength',text:'示例：结尾展示孩子实际使用自己选的物品，呼应开头。'};p.videoAnalysis=a;persist('示例观察已填入，可修改');closeModal();render();return;}
if(action==='analysis-generate'){saveAnalysisForm();p.analysisReport=JimuAnalysis.generate(p,S.projects,C);persist('视频分析已生成，结论等待编导判断');render();$('#analysis-report')?.scrollIntoView({behavior:'smooth',block:'start'});return;}
if(action==='analysis-export'){if(!p.analysisReport)throw Error('请先生成视频分析。');download('积木工作台-视频分析-'+p.title.slice(0,35)+'.txt',analysisExport(p),'text/plain;charset=utf-8');toast('视频分析报告已导出');return;}
if(action==='analysis-to-review'){saveAnalysisForm();if(!JimuAnalysis.isCurrent(p))throw Error('观察或数据已更新，请先重新生成视频分析。');if(p.review){confirmModal('将内容分析带入本次复盘','将替换当前尚未确认的参考建议、逐条选择和最终方向草稿。新的建议仍需要你重新判断确认。','analysis-confirm-review',id,'替换未确认建议');return;}applyAnalysisReview(p);return;}
if(action==='analysis-confirm-review'){closeModal();applyAnalysisReview(p);}
}catch(err){toast(err.message,true);}});
function applyAnalysisReview(p){const r=JimuAnalysis.combinedReview(p,S.projects,C);p.review=r;p.decisions=r.suggestions.map(s=>({choice:'',text:s.text}));delete p.directionDraft;persist('内容分析已带入复盘，等待你逐条确认');go('project/'+p.id);}
document.addEventListener('submit',e=>{if(e.target.id!=='analysis-form')return;e.preventDefault();try{saveAnalysisForm();toast('内容观察已保存');render();}catch(err){toast(err.message,true);}});
document.addEventListener('change',e=>{const input=e.target;if(input.id!=='analysis-video-input'||!input.files[0])return;const file=input.files[0],id=input.dataset.id;if(!file.type.startsWith('video/')){toast('请选择视频文件。',true);input.value='';return;}const previous=analysisFiles.get(id);if(previous)URL.revokeObjectURL(previous.url);analysisFiles.set(id,{url:URL.createObjectURL(file),name:file.name,size:file.size});mountAnalysisPlayer(id);});
